INSERT INTO engine_bug_queue (bug_class, title, severity, owner_cluster, root_cause, prevention_rule, probe_type, probe_logic, status, concepts_affected, fixed_in_files, discovered_in_session, row_type, fixed_at) VALUES
('sr_apparatus_is_centred_on_the_world_origin_in_x_only_so_a_flat_region_state_renders_in_the_top_half', 'SR-D10 shifts the apparatus onto the world origin along x only, so a state whose content is entirely above the axis of revolution renders in the upper half of the canvas with the lower half empty', 'MODERATE', 'peter_parker:field3d_surgeon', 'srShiftX = -(domain0 + domain1) / 2 (src/lib/renderers/field_3d_renderer.ts) exists because the camera TARGET is not authorable (the open MAJOR row field3d_scenario_renders_offcentre_because_camera_target_is_not_authorable), and it centres the drawn apparatus horizontally. There is no srShiftY. The camera therefore looks at graph y = 0, which is the axis of revolution. A state that draws a SOLID is unaffected, because a revolved solid straddles that axis: measured max |NDC| stays inside the gate floors on every 3D state. But a state that draws only the FLAT REGION has all its content in graph y in [0, 2] — entirely above the axis — so it renders in the top half of the frame with roughly 50 percent of the canvas empty beneath it. MEASURED on solids_of_revolution STATE_1 frozen frame (1280x720): the drawn graph spans y approximately 110 to 360 px, i.e. the lower 360 px carry nothing. Rule 34 wants the canvas dominated by the moving picture; half of it is background. WHY IT IS NOT MERELY COSMETIC: the concept opens on this state, so it is the first frame a teacher sees, and it is the chapter-continuity frame (arc rule 5) that is supposed to be recognisably Act II last object. WHY IT IS NOT FIXED IN THE AUTHORING PASS: adding a vertical shift moves every mesh, the axis rod, the frame group and the DOM tick projection together, and it changes the world coordinates the camera solve was computed against — which means the architect solved camera table (skeleton section 11) and the gate sections 11 and 12 that assert its NDC and frame-fill numbers all have to be re-solved and re-verified. That is a design decision about the scenario framing, not a mechanical repair.', 'A scenario that centres its apparatus on the world origin because the camera target is not authorable must centre it on BOTH axes, or state in its own comment which axis it deliberately leaves un-centred and why. A half-applied workaround reads as a complete one at every later review: SR-D10 is documented as "the whole apparatus is shifted onto the world origin", and that sentence is what a reader checks against, not the code.', 'js_eval', 'For each state, project the drawn content bounding box at the authored camera_position (FOV 60, 16:9) and assert the vertical CENTRE of that box sits within 0.15 NDC of the frame centre. STATE_1 of solids_of_revolution fails today; every solid-bearing state passes, which is what makes the defect easy to miss on a fleet sweep that samples one state per concept.', 'OPEN', ARRAY['solids_of_revolution']::text[], ARRAY[]::text[], 'session_2026-08-27_sr_concept_authoring', 'incident', NULL)
ON CONFLICT (bug_class) DO UPDATE SET
  title = EXCLUDED.title,
  severity = EXCLUDED.severity,
  owner_cluster = EXCLUDED.owner_cluster,
  root_cause = EXCLUDED.root_cause,
  prevention_rule = EXCLUDED.prevention_rule,
  probe_logic = EXCLUDED.probe_logic,
  status = EXCLUDED.status,
  concepts_affected = EXCLUDED.concepts_affected,
  fixed_in_files = EXCLUDED.fixed_in_files,
  fixed_at = EXCLUDED.fixed_at
WHERE engine_bug_queue.root_cause NOT LIKE '%SR_SHIFT_Y_2026_08_27%'
  AND engine_bug_queue.status NOT IN ('FIXED', 'FALSE_POSITIVE');

