INSERT INTO engine_bug_queue (bug_class, title, severity, owner_cluster, root_cause, prevention_rule, probe_type, probe_logic, status, concepts_affected, fixed_in_files, discovered_in_session, row_type, fixed_at) VALUES
('sr_dom_tick_numbers_have_no_depth_so_they_paint_over_the_solid_that_encloses_their_axis', 'The axis tick numbers are DOM nodes positioned per frame from a projection, so they carry no depth and render ON TOP of a translucent solid that geometrically encloses them', 'MODERATE', 'peter_parker:field3d_surgeon', 'srPlaceTickNodes (src/lib/renderers/field_3d_renderer.ts) positions the tick container children from nlbProjPx each frame. This is the deliberate answer to blocker 2: a world-space sprite cannot control its glyph height in device px, decollides blind to the projection, and is invisible to every DOM probe — three OPEN scars the DOM route dissolves. The cost, which the decision did not record, is that a DOM node has no z relationship to the THREE scene: it is painted after, always. When the revolved solid encloses the axes — which is the normal case for this scenario, not an edge case — the numbers float ON the solid instead of behind it. OBSERVED on solids_of_revolution STATE_5 (the primary aha): the tick labels -2, -1, 0, 1, 2 read as ink sitting on the surface of the ball. Also visible on STATE_6 and STATE_7. A SECOND, SEPARATE SYMPTOM ON THE SAME MECHANISM: STATE_3 puts the camera 12 degrees off the axis of revolution (required, so the disc face still projects as a circle at the worst position it reaches), which makes the x-axis nearly end-on. Its five tick numbers 0..4 then project into roughly 60 px and bunch into an unreadable cluster. The decollider drops overlapping labels, so no label LIES — but the axis reads as clutter rather than as a scale.', 'Any overlay drawn outside the 3D scene graph is unconditionally in front of it. Before choosing a DOM overlay for something that lives at a world POSITION, state what happens when scene geometry occupies that position — and if the answer is "it paints over it", say so beside the decision instead of leaving it to the first concept that authors a solid big enough to find out.', 'js_eval', 'With a state that renders a closed solid, read the tick container children screen positions and test each against the projected silhouette of the solid. Any tick whose position falls INSIDE the silhouette is painting over geometry that encloses it. On solids_of_revolution STATE_5 at the authored pin, five of the ticks fall inside the ball.', 'OPEN', ARRAY['solids_of_revolution']::text[], ARRAY[]::text[], 'session_2026-08-27_sr_concept_authoring', 'incident', NULL)
ON CONFLICT (bug_class) DO UPDATE SET
  title = EXCLUDED.title,
